<script setup>
import { Head, useForm } from '@inertiajs/vue3';
import AdminLayout from '@/Shared/Layouts/AdminLayout.vue';
const props=defineProps({post:Object,products:{type:Array,default:()=>[]}});
const form=useForm({title:props.post?.title||'',slug:props.post?.slug||'',excerpt:props.post?.excerpt||'',body:props.post?.body||'',type:props.post?.type||'video',category:props.post?.category||'',video_url:props.post?.video_url||'',poster_url:props.post?.poster_url||'',source_url:props.post?.source_url||'',source_name:props.post?.source_name||'',status:props.post?.status==='review'?'review':'draft',published_at:props.post?.published_at||'',rights_confirmed:!!props.post?.rights_confirmed,editorial_checked:!!props.post?.editorial_checked,product_ids:props.post?.product_ids||props.post?.products?.map(p=>p.id)||[]});
const publish=useForm({});const fields={title:'Título',slug:'Slug',excerpt:'Resumo',body:'Texto completo (texto puro)',category:'Categoria',video_url:'URL local do vídeo (.mp4 / .webm)',poster_url:'URL local da capa',source_url:'URL HTTPS da fonte',source_name:'Nome da fonte',published_at:'Data de publicação (opcional)'};
function save(){props.post?form.put(`/admin/editorial/posts/${props.post.id}`):form.post('/admin/editorial/posts');}
</script>
<template><AdminLayout><Head title="Editar publicação"/><section class="p-6 max-w-4xl"><a href="/admin/editorial/posts">← Editorial</a><h1 class="text-2xl font-bold my-4">{{post?'Editar publicação':'Nova publicação'}}</h1><p class="my-3">Salvar não publica. Alterações em conteúdo publicado voltam a rascunho. Revise fatos, fontes, direitos e produtos; conteúdo de IA nunca deve ser autopublicado.</p><form @submit.prevent="save" class="space-y-4"><div v-for="(label,key) in fields" :key="key"><label :for="`field-${key}`" class="block font-medium">{{label}}</label><textarea v-if="['body','excerpt'].includes(key)" :id="`field-${key}`" v-model="form[key]" :rows="key==='body'?12:3" class="border rounded w-full p-2"></textarea><input v-else :id="`field-${key}`" v-model="form[key]" class="border rounded w-full p-2" :required="['title','slug','category'].includes(key)"><p v-if="form.errors[key]" role="alert" class="text-red-700">{{form.errors[key]}}</p></div><label class="block">Tipo <select v-model="form.type" class="border p-2"><option value="video">Vídeo</option><option value="recipe">Receita</option><option value="news">Notícia</option></select></label><label class="block">Etapa <select v-model="form.status" class="border p-2"><option value="draft">Rascunho</option><option value="review">Em revisão</option></select></label><fieldset class="border p-4"><legend>Produtos contextuais</legend><p v-if="!products.length">Nenhum produto disponível para vincular.</p><label v-for="p in products" :key="p.id" class="block py-2"><input v-model="form.product_ids" type="checkbox" :value="p.id"> {{p.name}}</label></fieldset><label class="block"><input type="checkbox" v-model="form.rights_confirmed"> Confirmo os direitos de uso da mídia e do conteúdo.</label><label class="block"><input type="checkbox" v-model="form.editorial_checked"> Revisei fatos, fontes, texto e adequação editorial.</label><p v-for="(error,key) in form.errors" :key="key" role="alert" class="text-red-700">{{error}}</p><button class="rounded bg-black text-white px-5 py-3" :disabled="form.processing">{{form.processing?'Salvando…':'Salvar rascunho / revisão'}}</button><p v-if="form.recentlySuccessful" role="status">Alterações salvas pelo servidor.</p></form><div v-if="post" class="my-6 border-t pt-5"><a :href="`/admin/editorial/posts/${post.id}/preview`">Abrir prévia privada</a><p class="my-3">Salve as confirmações e revise a prévia antes de publicar.</p><button class="border rounded p-3" :disabled="publish.processing || form.isDirty || !form.rights_confirmed || !form.editorial_checked" @click="publish.post(`/admin/editorial/posts/${post.id}/publish`)">Publicar após revisão</button><button v-if="post.status==='published'" class="border rounded p-3 ml-3" :disabled="publish.processing" @click="publish.post(`/admin/editorial/posts/${post.id}/unpublish`)">Despublicar</button><p v-for="(error,key) in publish.errors" :key="key" role="alert">{{error}}</p></div></section></AdminLayout></template>
